//! How deeply a CEL expression nests, measured before the `cel` crate sees it.
//!
//! The crate's parser is generated by ANTLR and recurses: every bracket and
//! every `? :` goes about ten grammar rules deeper, each its own stack
//! frame. Its own recursion limit (96 levels) counts only one of those
//! rules, and is checked on the way down, so the frames are already on the
//! stack when it refuses. Unoptimised, a dozen `{` need more than a 2 MiB
//! thread's stack. Stack use isn't something Rust can check and turn into
//! an error, so the depth has to be known before the parse starts.
//!
//! [`nesting_depth`] scans the expression once, in a loop, reading it the
//! way CEL's lexer does: brackets in strings and comments don't count. Where
//! the lexer would fail, the scan refuses instead of guessing. After a lexer
//! error ANTLR drops the characters it had read and the one it failed on,
//! then carries on, so `{&}` reaches the parser as `{{`, and an unclosed
//! string's brackets as code. Every such input is invalid CEL anyway.

/// The deepest a `match` or `deny` expression may nest brackets (`(`, `[`,
/// `{`) and conditionals (`? :`), counted together.
///
/// Real policies nest two or three levels. At 32, parsing stays well inside
/// a 2 MiB thread, the smallest stack any caller gives it (a tokio
/// worker's), with `cel` optimised as release builds and `Cargo.toml`'s
/// dev profile build it.
pub const MAX_EXPRESSION_NESTING: usize = 32;

/// Why an expression couldn't be scanned: CEL's lexer would fail on it too.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum Malformed {
    /// A string or bytes literal with no closing quote, or a one-line one
    /// that runs into a newline.
    UnterminatedString,
    /// A backslash escape CEL doesn't have.
    InvalidEscape,
    /// A backtick that doesn't start a closed `` `escaped.identifier` ``.
    UnclosedIdentifier,
    /// `&`, `|` or `=` on its own, not in `&&`, `||` or `==`.
    LoneOperator(char),
}

impl std::fmt::Display for Malformed {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Malformed::UnterminatedString => write!(f, "a string literal isn't closed"),
            Malformed::InvalidEscape => write!(f, "a string literal has an invalid escape"),
            Malformed::UnclosedIdentifier => write!(f, "a backtick-quoted name isn't closed"),
            Malformed::LoneOperator(operator) => write!(
                f,
                "{operator:?} on its own isn't an operator; did you mean {operator}{operator}?"
            ),
        }
    }
}

/// The deepest nesting in `expression`: brackets plus the conditionals
/// open inside them. Stops once the depth passes `limit`, so the caller
/// learns only that it's too deep.
pub(super) fn nesting_depth(expression: &str, limit: usize) -> Result<usize, Malformed> {
    let bytes = expression.as_bytes();
    // One entry per open bracket, over the bottom level, counting the
    // conditionals open at that level: a conditional's `else` branch runs
    // to the end of its bracket, or to a comma inside one.
    let mut levels: Vec<usize> = vec![0];
    let mut depth = 0;
    let mut deepest = 0;
    let mut i = 0;
    while i < bytes.len() {
        let next = bytes.get(i + 1).copied();
        match bytes[i] {
            b'(' | b'[' | b'{' => {
                levels.push(0);
                depth += 1;
                i += 1;
            }
            b')' | b']' | b'}' => {
                // A stray closing bracket is a parse error. Keeping the
                // bottom level only ever over-counts.
                if levels.len() > 1
                    && let Some(open) = levels.pop()
                {
                    depth -= 1 + open;
                }
                i += 1;
            }
            b'?' => {
                if let Some(open) = levels.last_mut() {
                    *open += 1;
                }
                depth += 1;
                i += 1;
            }
            b',' => {
                // At the top level a comma is a parse error, so it ends
                // nothing there.
                if levels.len() > 1
                    && let Some(open) = levels.last_mut()
                {
                    depth -= *open;
                    *open = 0;
                }
                i += 1;
            }
            operator @ (b'&' | b'|' | b'=') => {
                if next != Some(operator) {
                    return Err(Malformed::LoneOperator(char::from(operator)));
                }
                i += 2;
            }
            // `!=`, `<=` and `>=` are one token: their `=` isn't a lone one.
            b'!' | b'<' | b'>' => i += if next == Some(b'=') { 2 } else { 1 },
            b'/' if next == Some(b'/') => i = skip_comment(bytes, i),
            b'"' | b'\'' => i = skip_string(bytes, i, false)?,
            b'0'..=b'9' => i = skip_number(bytes, i),
            b'`' => i = skip_escaped_identifier(bytes, i)?,
            c if c.is_ascii_alphabetic() || c == b'_' => i = skip_word(bytes, i)?,
            // Anything else the lexer drops on its own, as this does.
            _ => i += 1,
        }
        deepest = deepest.max(depth);
        if deepest > limit {
            return Ok(deepest);
        }
    }
    Ok(deepest)
}

/// Skip a `//` comment, which runs to the end of the line.
fn skip_comment(bytes: &[u8], start: usize) -> usize {
    bytes[start..]
        .iter()
        .position(|&b| b == b'\n')
        .map_or(bytes.len(), |offset| start + offset)
}

/// Skip a number, as CEL's lexer reads one: `0x` and hex digits, or
/// digits, a fraction and an exponent, then an optional `u`. Stopping
/// exactly where the lexer does matters only before a quote: `1e5r'…'` is
/// a number and a raw string, `1er'…'` a number, the word `er` and an
/// ordinary string.
fn skip_number(bytes: &[u8], start: usize) -> usize {
    let digits = |from: usize, hex: bool| {
        let mut end = from;
        while end < bytes.len()
            && (bytes[end].is_ascii_digit() || (hex && bytes[end].is_ascii_hexdigit()))
        {
            end += 1;
        }
        end
    };
    let at = |index: usize| bytes.get(index).copied();
    if at(start) == Some(b'0')
        && at(start + 1) == Some(b'x')
        && at(start + 2).is_some_and(|b| b.is_ascii_hexdigit())
    {
        let end = digits(start + 2, true);
        return end + usize::from(matches!(at(end), Some(b'u' | b'U')));
    }
    let mut end = digits(start, false);
    let mut float = false;
    if at(end) == Some(b'.') && at(end + 1).is_some_and(|b| b.is_ascii_digit()) {
        end = digits(end + 1, false);
        float = true;
    }
    if matches!(at(end), Some(b'e' | b'E')) {
        let sign = usize::from(matches!(at(end + 1), Some(b'+' | b'-')));
        if at(end + 1 + sign).is_some_and(|b| b.is_ascii_digit()) {
            end = digits(end + 1 + sign, false);
            float = true;
        }
    }
    if !float && matches!(at(end), Some(b'u' | b'U')) {
        end += 1;
    }
    end
}

/// Skip a word: an identifier or keyword, or the prefix of a string. CEL
/// reads `r'…'` as a raw string, `b'…'` as bytes and `br'…'` as raw bytes,
/// but `rb'…'` or `bar'…'` as a word and then an ordinary string.
fn skip_word(bytes: &[u8], start: usize) -> Result<usize, Malformed> {
    let at = |index: usize| bytes.get(index).copied();
    let quote = |index: usize| matches!(at(index), Some(b'"' | b'\''));
    let raw = |index: usize| matches!(at(index), Some(b'r' | b'R'));
    let bytes_prefix = matches!(at(start), Some(b'b' | b'B'));
    if bytes_prefix && quote(start + 1) {
        return skip_string(bytes, start + 1, false);
    }
    if bytes_prefix && raw(start + 1) && quote(start + 2) {
        return skip_string(bytes, start + 2, true);
    }
    if raw(start) && quote(start + 1) {
        return skip_string(bytes, start + 1, true);
    }
    let mut end = start;
    while end < bytes.len() && (bytes[end].is_ascii_alphanumeric() || bytes[end] == b'_') {
        end += 1;
    }
    Ok(end)
}

/// Skip an escaped identifier, `` `a.b/c` ``, whose `/` mustn't start a
/// comment.
fn skip_escaped_identifier(bytes: &[u8], start: usize) -> Result<usize, Malformed> {
    let inside =
        |b: &u8| b.is_ascii_alphanumeric() || matches!(b, b'_' | b'.' | b'-' | b'/' | b' ');
    let length = bytes[start + 1..].iter().take_while(|b| inside(b)).count();
    if length == 0 || bytes.get(start + 1 + length) != Some(&b'`') {
        return Err(Malformed::UnclosedIdentifier);
    }
    Ok(start + length + 2)
}

/// Skip a string literal whose opening quote is at `start`: one quote or
/// three, raw (no escapes) or not. Returns the index after its closing
/// quote.
fn skip_string(bytes: &[u8], start: usize, raw: bool) -> Result<usize, Malformed> {
    let quote = bytes[start];
    let triple = bytes.get(start + 1) == Some(&quote) && bytes.get(start + 2) == Some(&quote);
    let mut i = if triple { start + 3 } else { start + 1 };
    while i < bytes.len() {
        let c = bytes[i];
        if triple
            && c == quote
            && bytes.get(i + 1) == Some(&quote)
            && bytes.get(i + 2) == Some(&quote)
        {
            return Ok(i + 3);
        }
        if !triple && c == quote {
            return Ok(i + 1);
        }
        if !triple && (c == b'\n' || c == b'\r') {
            return Err(Malformed::UnterminatedString);
        }
        if c == b'\\' && !raw {
            i += escape_length(&bytes[i..]).ok_or(Malformed::InvalidEscape)?;
        } else {
            i += 1;
        }
    }
    Err(Malformed::UnterminatedString)
}

/// The length of the escape sequence at the start of `bytes` (which starts
/// with a backslash), or `None` when CEL has no such escape.
fn escape_length(bytes: &[u8]) -> Option<usize> {
    let hex = |from: usize, count: usize| {
        bytes
            .get(from..from + count)
            .is_some_and(|run| run.iter().all(u8::is_ascii_hexdigit))
    };
    match bytes.get(1)? {
        b'a' | b'b' | b'f' | b'n' | b'r' | b't' | b'v' | b'"' | b'\'' | b'\\' | b'?' | b'`' => {
            Some(2)
        }
        b'0'..=b'3'
            if bytes
                .get(2..4)
                .is_some_and(|run| run.iter().all(|b| (b'0'..=b'7').contains(b))) =>
        {
            Some(4)
        }
        b'x' | b'X' if hex(2, 2) => Some(4),
        b'u' if hex(2, 4) => Some(6),
        b'U' if hex(2, 8) => Some(10),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn depth(expression: &str) -> usize {
        nesting_depth(expression, usize::MAX).unwrap()
    }

    #[test]
    fn a_flat_expression_has_no_depth() {
        assert_eq!(depth("app.name == 'web' && app.replicas > 2"), 0);
        assert_eq!(depth(""), 0);
    }

    #[test]
    fn every_kind_of_bracket_counts() {
        assert_eq!(depth("size(app.name) > 1"), 1);
        assert_eq!(depth("[[1]] == [[1]]"), 2);
        assert_eq!(depth("{'a': {'b': (1)}}"), 3);
        assert_eq!(depth(&"{".repeat(150)), 150);
    }

    #[test]
    fn a_conditional_nests_until_its_bracket_closes() {
        assert_eq!(depth("a ? 1 : b ? 2 : c ? 3 : 4"), 3);
        assert_eq!(depth("(a ? 1 : 2) + (b ? 3 : 4)"), 2);
        assert_eq!(depth(&format!("{}1", "true ? 1 : ".repeat(40))), 40);
    }

    #[test]
    fn a_comma_ends_a_conditional_inside_brackets_only() {
        assert_eq!(depth("[a ? 1 : 2, b ? 3 : 4, c ? 5 : 6]"), 2);
        // At the top level a comma is a parse error, so it ends nothing.
        assert_eq!(depth("a ? 1 : 2, b ? 3 : 4"), 2);
    }

    #[test]
    fn brackets_in_strings_and_comments_dont_count() {
        assert_eq!(depth("app.name == '((((('"), 0);
        assert_eq!(depth("app.name == \"[[[\" // {{{{"), 0);
        assert_eq!(depth("app.name.matches(r'^(a|b)\\d+$')"), 1);
        assert_eq!(depth("app.name == '''{{\n{{'''"), 0);
        assert_eq!(depth("b'(((' == b\"\\x28\""), 0);
    }

    #[test]
    fn closing_brackets_in_strings_cant_hide_open_ones() {
        // A naive count would let `)` inside a string cancel a real `(`.
        let hidden = format!("{}')))))))' + {}", "(".repeat(20), "(".repeat(20));
        assert_eq!(depth(&hidden), 40);
        // A comment hides its brackets from CEL, so it hides them here.
        let commented = format!("{} // )))))))\n{}", "(".repeat(20), "(".repeat(20));
        assert_eq!(depth(&commented), 40);
    }

    #[test]
    fn raw_strings_are_read_where_cel_reads_them() {
        // `r'\'` is a complete raw string, so the brackets after it count.
        assert_eq!(depth(&format!("r'\\' + {}", "(".repeat(5))), 5);
        // `1e5r'\'` is a number and a raw string.
        assert_eq!(depth(&format!("1e5r'\\' + {}", "(".repeat(5))), 5);
        // `bar'…'` is a word and an ordinary string, whose `\'` is an escape.
        assert_eq!(depth("bar'\\'' + (1)"), 1);
    }

    #[test]
    fn an_escaped_identifier_cant_start_a_comment() {
        assert_eq!(depth(&format!("`a//b` + {}", "(".repeat(5))), 5);
    }

    #[test]
    fn operators_are_read_whole() {
        assert_eq!(depth("a == 1 && b != 2 || c <= 3 && d >= 4"), 0);
        assert_eq!(depth("!(a)"), 1);
    }

    #[test]
    fn input_the_lexer_would_drop_characters_from_is_refused() {
        let refused = |expression: &str| nesting_depth(expression, usize::MAX).unwrap_err();
        // ANTLR would drop each `}` after an `&`: the parser sees `{{{`.
        assert_eq!(refused(&"{&}".repeat(50)), Malformed::LoneOperator('&'));
        assert_eq!(refused("a | b"), Malformed::LoneOperator('|'));
        assert_eq!(refused("a = b"), Malformed::LoneOperator('='));
        // Unclosed, the lexer would drop "`a //" and the `(` after it.
        assert_eq!(refused("`a //(((("), Malformed::UnclosedIdentifier);
        assert_eq!(refused("``"), Malformed::UnclosedIdentifier);
    }

    #[test]
    fn a_string_cel_would_refuse_is_refused() {
        let refused = |expression: &str| nesting_depth(expression, usize::MAX).unwrap_err();
        assert_eq!(
            refused(&format!("'{}", "(".repeat(200))),
            Malformed::UnterminatedString
        );
        assert_eq!(refused("'abc\n' + 1"), Malformed::UnterminatedString);
        assert_eq!(refused("'\\q'"), Malformed::InvalidEscape);
        assert_eq!(refused("'''abc"), Malformed::UnterminatedString);
    }

    #[test]
    fn the_scan_stops_once_past_the_limit() {
        assert_eq!(nesting_depth(&"(".repeat(100_000), 5), Ok(6));
    }

    #[test]
    fn a_stray_closing_bracket_never_lowers_the_count() {
        assert_eq!(depth(&format!(")))){}", "(".repeat(10))), 10);
    }
}
